// The terminal recordings are SVG images (`assets/apic-ui.svg` and the
// like, generated by `task shots`). On a phone they keep their width and
// the paragraph around them scrolls, which makes it a scroll region, so
// it gets a tabindex for keyboard users and a class for the styles. An
// animated recording with a poster beside it (`<name>-poster.svg`) is
// served through a <picture> whose source applies under
// prefers-reduced-motion: the page evaluates that media query, which an
// SVG image document cannot be trusted to do in every browser.
import fs from 'node:fs';
import path from 'node:path';
import { visit } from 'unist-util-visit';

const publicRoot = path.resolve('public');

export default function rehypeRecordings() {
	return (tree) => {
		visit(tree, { type: 'element', tagName: 'p' }, (p) => {
			const children = p.children.filter((c) => c.type !== 'text' || c.value.trim());
			if (children.length !== 1) return;
			const [img] = children;
			if (img.type !== 'element' || img.tagName !== 'img') return;
			const src = String(img.properties?.src ?? '');
			if (!src.startsWith('/assets/') || !src.endsWith('.svg')) return;
			p.properties = { ...p.properties, className: ['recording'], tabIndex: 0 };
			const poster = src.replace(/\.svg$/, '-poster.svg');
			if (!fs.existsSync(path.join(publicRoot, poster))) return;
			p.children = [
				{
					type: 'element',
					tagName: 'picture',
					properties: {},
					children: [
						{
							type: 'element',
							tagName: 'source',
							properties: { media: '(prefers-reduced-motion: reduce)', srcSet: poster },
							children: [],
						},
						img,
					],
				},
			];
		});
	};
}
